 "content": "def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) != 2:
        return out
    h, w = len(grid), len(grid[0])

    def neighborhood_count(pos):
        r0, c0 = pos
        return sum(
            1 for r, row in enumerate(grid) for c, v in enumerate(row)
            if v != 0 and v != 5 and (r, c) != pos
            and abs(r-r0) <= 3 and abs(c-c0) <= 3
        )

    source = max(markers, key=neighborhood_count)
    target = markers[1] if source == markers[0] else markers[0]
    sr, sc = source
    tr, tc = target
    offsets = [(r-sr, c-sc, grid[r][c])
               for r, row in enumerate(grid) for c, v in enumerate(row)
               if v != 0 and v != 5 and abs(r-sr) <= 3 and abs(c-sc) <= 3]
    out[tr][tc] = 0
    for dr, dc, color in offsets:
        rr, cc = tr+dr, tc+dc
        if 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = color
    return out
